import{_ as l,a0 as o,w as d,s as r,I as t,x as e,a1 as i,A as n,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"学习如何高效地使用 man 页 | LCTT x X-CMD","titleTemplate":false,"description":"学习如何高效地使用 man 页 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"学习如何高效地使用 man 页 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"学习如何高效地使用 man 页 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171215 Learn To Use Man Pages Efficiently","title":"学习如何高效地使用 man 页","tag":"201712","desc":""},"relativePath":"201712/20171215 Learn To Use Man Pages Efficiently.md","filePath":"[post].md"}'),c={name:"201712/20171215 Learn To Use Man Pages Efficiently.md"};function h(g,a,m,k,u,b){const s=o("Link");return d(),r("div",null,[a[19]||(a[19]=t("h1",{id:"学习如何高效地使用-man-页",tabindex:"-1"},[e("学习如何高效地使用 man 页 "),t("a",{class:"header-anchor",href:"#学习如何高效地使用-man-页","aria-label":"Permalink to “学习如何高效地使用 man 页”"},"​")],-1)),t("p",null,[a[1]||(a[1]=e("不久前，我们发布了一篇简短的指引描述了如何轻易地",-1)),i(s,{href:"https://www.ostechnix.com/easily-recall-forgotten-linux-commands/"},{default:n(()=>[...a[0]||(a[0]=[e("回忆起忘记的 Linux 命令 ",-1)])]),_:1}),a[2]||(a[2]=e("。那篇指引对于无法记住命令的人来说真的非常有用。今天，我们就来学习一下如何高效而又迅速地从 man 页中获取你所需要的信息。如你所知，一个标准的 man 页分成很多个部分，每部分都有一个独立的标题。当你想查看特定的标志/选项时，可能需要向下滚动很长时间才能找到。这是个效率底下而且很耗时间的过程。这也是为什么学会高效使用 man 页来精确定位你想要的内容。",-1))]),a[20]||(a[20]=p(`<p>在本文中，我会分享一些常用的跟 man 页相关的重要技巧。</p><h3 id="学习高效地使用-man-页" tabindex="-1">学习高效地使用 Man 页 <a class="header-anchor" href="#学习高效地使用-man-页" aria-label="Permalink to “学习高效地使用 Man 页”">​</a></h3><h4 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to “基础用法”">​</a></h4><p>我们都知道，我们可以使用类似下面的命令来打开关于某个命令（比如 <code>mkdir</code>）的 man 页：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mkdir</span></span></code></pre></div><p>可以使用 <code>空格</code>，<code>d</code>，<code>b</code> 以及上下箭头等来浏览 man 页。要跳转道 man 页的末尾，可以按 <code>End</code> 键而想跳转到 man 页的头部则可以按 <code>Home</code> 键。在当前打开的 man 页中按下 <code>h</code> 键会显示所有有用的键盘快捷键和一般用法。（LCTT 译注：这些快捷键其实是 man 所使用的 less 分页器的快捷键）</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-4.png" alt=""></p><p>按 <code>q</code> 可以退出 man 页。</p><h4 id="回忆起忘记的命令" tabindex="-1">回忆起忘记的命令 <a class="header-anchor" href="#回忆起忘记的命令" aria-label="Permalink to “回忆起忘记的命令”">​</a></h4><p>对于那些不知道想要哪个命令的家伙，可以去查看一下我第一段中提到的那个链接。使用 man 页我们也能做到这一点。假设说，你想要创建一个目录，而你忘记了使用哪个命令来创建目录。</p><p>为了回忆起那个忘记的命令，可以将 man 和 <code>grep</code> 命令联用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man -k directory | grep create</span></span></code></pre></div><p>输出结果为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CURLOPT_NEW_DIRECTORY_PERMS (3) - permissions for remotely created directories</span></span>
<span class="line"><span>libssh2_sftp_mkdir_ex (3) - create a directory on the remote file system</span></span>
<span class="line"><span>mkdir (2) - create a directory</span></span>
<span class="line"><span>mkdirat (2) - create a directory</span></span>
<span class="line"><span>mkdtemp (3) - create a unique temporary directory</span></span>
<span class="line"><span>mkdtemp (3p) - create a unique directory or file</span></span>
<span class="line"><span>mkfontdir (1) - create an index of X font files in a directory</span></span>
<span class="line"><span>mklost+found (8) - create a lost+found directory on a mounted Linux second extended file。。。</span></span>
<span class="line"><span>mkstemp (3p) - create a unique directory</span></span>
<span class="line"><span>mktemp (1) - create a temporary file or directory</span></span>
<span class="line"><span>pam_mkhomedir (8) - PAM module to create users home directory</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-3.png" alt=""></p><p>你只需要阅读一下每个命令的描述然后挑选出合适的命令就行了。啊，现在你记起来了。<code>mkdir</code> 正式你想要的，对吧？就是那么简单。</p><h4 id="在-man-页中搜索" tabindex="-1">在 man 页中搜索 <a class="header-anchor" href="#在-man-页中搜索" aria-label="Permalink to “在 man 页中搜索”">​</a></h4><p>若你在 man 页中想要查找特定字符串。只需要输入 <code>/</code> （前斜线）再加上你想要搜索的字符串，像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/&lt;search_string&gt; 或 &lt;pattern&gt;</span></span></code></pre></div><p>假设你正在查看 <code>mount</code> 命令的 man 页，想要寻找关于 <code>-bind</code> 选项的相关信息。可以输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/bind</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-5.png" alt=""></p><p>当前 man 页中任何匹配搜索字符串的内容都会被高亮显示。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-6.png" alt=""></p><p>按下 <code>n</code> 和 <code>SHIFT+n</code> 来查看下一个/上一个匹配的地方。</p><p><code>/</code> 模式（或者说字符串）会向前搜索匹配行。你也可以使用 <code>?</code> 模式进行向后搜索。这当你在 man 页的末尾或中间位置时非常有用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?bind</span></span></code></pre></div><p>若想只显示匹配行，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&amp;bind</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-8.png" alt=""></p><p>使用这种方法，你无需使用 <code>n</code> 和 <code>SHIFT+n</code> 来滚动到下一个/上一个匹配的位置。<code>&amp;</code> 模式只会显示那些包含搜索内容的行，其他的内容全都被省略掉。</p><h4 id="不打开-man-页而进行搜索" tabindex="-1">不打开 man 页而进行搜索 <a class="header-anchor" href="#不打开-man-页而进行搜索" aria-label="Permalink to “不打开 man 页而进行搜索”">​</a></h4><p>也可以在不打开 man 页的前提下搜索指定选项的信息。</p><p>比如，你想了解 <code>mkdir</code> 命令中的 <code>-m</code> 选项的相关信息。可以运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mkdir | grep -e &#39;-m&#39;</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mkdir | grep -- &#39;-m&#39;</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-1.png" alt=""></p><p>这个命令会显示出 <code>mkdir</code> 命令 man 页中第一次出现 <code>-m</code> 时的内容。从上面命令中我们可以看到 <code>-m</code> 表示的是 “MODE”（<code>chmod</code>）。</p><p>如果你想阅读 <code>mkdir</code> 命令的完整 man 页，但是要跳过第一次出现 <code>-m</code> 之前的内容，可以使用下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mkdir | less +/-m</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-2-1.png" alt=""></p><p>这是另一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mount | less +/--bind</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-7.png" alt=""></p><p>按下 <code>n</code> 或 <code>SHIFT+n</code> 可以浏览下一个/上一个匹配的位置。</p>`,46)),t("p",null,[a[4]||(a[4]=e("参考阅读：",-1)),i(s,{href:"https://www.ostechnix.com/3-good-alternatives-man-pages-every-linux-user-know/"},{default:n(()=>[...a[3]||(a[3]=[e("每个 Linux 用户都应该知道的 3 个 man 页替代品",-1)])]),_:1}),a[5]||(a[5]=e("。",-1))]),a[21]||(a[21]=p('<h4 id="将完整的-man-页导出到文本文件中" tabindex="-1">将完整的 man 页导出到文本文件中 <a class="header-anchor" href="#将完整的-man-页导出到文本文件中" aria-label="Permalink to “将完整的 man 页导出到文本文件中”">​</a></h4><p>我们可以将指定命令的完整 man 页导出成文本文件。方法是运行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mount &gt; mount.txt</span></span></code></pre></div><p>该命令会将 <code>mount</code> 命令的 man 页导出到当前目录的 <code>mount.txt</code> 文件中。</p><p>也可以获取一个简化版的 man 页，没有退格和下划线，方法是使用下面命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mount | col -b &gt; mount.txt</span></span></code></pre></div><p>要了解更多关于 man 页的详细信息，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man man</span></span></code></pre></div><p>该命令会显示出关于 man 的 man 页。这些技巧都很基础但很实用。它们会节省你很多的时间而且能免去很多的滚动操作。</p><p>今天的内容就到这了。希望对你有帮助。更多好文即将到来。准备好哦！</p><p>Cheers！</p><hr>',12)),t("p",null,[a[7]||(a[7]=e("via: ",-1)),i(s,{href:"https://www.ostechnix.com/learn-use-man-pages-efficiently/"},{default:n(()=>[...a[6]||(a[6]=[e("https://www.ostechnix.com/learn-use-man-pages-efficiently/",-1)])]),_:1})]),t("p",null,[a[11]||(a[11]=e("作者：",-1)),i(s,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...a[8]||(a[8]=[e("SK",-1)])]),_:1}),a[12]||(a[12]=e(" 译者：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[9]||(a[9]=[e("lujun9972",-1)])]),_:1}),a[13]||(a[13]=e(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:n(()=>[...a[10]||(a[10]=[e("wxy",-1)])]),_:1})]),t("p",null,[a[16]||(a[16]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[14]||(a[14]=[e("LCTT",-1)])]),_:1}),a[17]||(a[17]=e(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:n(()=>[...a[15]||(a[15]=[e("Linux中国",-1)])]),_:1}),a[18]||(a[18]=e(" 荣誉推出",-1))])])}const w=l(c,[["render",h]]);export{x as __pageData,w as default};
